                AgentInput::from_user_text("go"),
                RunConfig::new().with_timeout(Duration::from_millis(50)),
            )
            .await
    })
    .await
    .expect("run must self-timeout within 5s");

    assert!(matches!(res, Err(RunError::Timeout)), "got {res:?}");
}

